const body = $json.body || $json;
const p = body.payload || {};

const dataObj = p.data ? new Date(p.data) : null;
const dataFmt = dataObj ? dataObj.toLocaleDateString('pt-PT', { day: '2-digit', month: 'long' }) : '';
const numeroBea = '351911150025';

const partes = ['✅ *' + (p.nomeCliente || 'Cliente') + '* confirmou a presença'];
if (p.servico) partes.push('— ' + p.servico);
if (dataFmt) partes.push('(dia ' + dataFmt + (p.hora ? ' às ' + p.hora : '') + ')');

return [{ json: { texto: partes.join(' ') + '.', numeroBea } }];

const body = $json.body || $json;
const p = body.payload || {};

const dataObj = p.data ? new Date(p.data) : null;
const hojeLisboa = new Date().toLocaleDateString('en-CA', { timeZone: 'Europe/Lisbon' });
const dataSessaoLisboa = dataObj ? dataObj.toLocaleDateString('en-CA', { timeZone: 'Europe/Lisbon' }) : null;
const ehHoje = dataSessaoLisboa === hojeLisboa;
const diaFmt = dataObj ? dataObj.toLocaleDateString('pt-PT', { day: 'numeric', timeZone: 'Europe/Lisbon' }) : '';
const quandoTexto = ehHoje ? `hoje, dia ${diaFmt}` : `dia ${diaFmt}`;

const servico = p.servico || 'a tua sessão';
const hora = p.hora || '';

const telefoneDigitos = (p.telefone || '').replace(/\D/g, '');
const telefone = telefoneDigitos.length === 9 ? '351' + telefoneDigitos : telefoneDigitos;

const texto = `Este é um lembrete de que a tua reserva de *${servico}* está marcada para ${quandoTexto}${hora ? `, às ${hora}h` : ''}.

⏳ Pedimos, por favor, que chegues apenas à hora marcada, para garantirmos a melhor organização e preparação da sala.

📍 *Morada*
Av. da República, nº 2208, Piso 2, Sala 2 Esquerda
4430-192 Vila Nova de Gaia

💳 *Métodos de pagamento aceites*
Numerário, MBWay ou Transferência

Qualquer dúvida, estamos disponíveis.

Será um gosto receber-te. 🌿

Essence Wellness`;

return [{ json: { telefone, texto } }];

// Fallback: o WhatsApp falhou (Evolution API) — envia a MESMA mensagem por
// email em vez de a perder. Simples: sem despejo de JSON, sem aviso genérico
// de "WhatsApp desligado" (isso é só o WF15) — é só o conteúdo real.
const texto = $json.texto || $json.textoWhatsapp || '(sem conteúdo disponível — a sessão continua registada no CRM)';
return [{ json: {
  to: 'geral@essencewellnesspt.com',
  subject: '⚠️ WhatsApp falhou — Sessão Confirmada (terapeuta)',
  body: `O envio por WhatsApp falhou (Evolution API) — aqui fica a mesma mensagem, por email:

${texto}`,
} }];

